  if (values.length === 0 || values[0] === null) return null;
  const root       = { value: values[0], left: null, right: null };
  const queue         = [root]; let index = 1;
  for (let i = 0; i < queue.length && index < values.length; i++) {
    const node = queue[i];
    for (const side of ['left', 'right']         ) {
      const value = values[index++];
      if (value !== null && value !== undefined) { const child       = { value, left: null, right: null }; node[side] = child; queue.push(child); }
    }
  }
  return root;
