function writeTree(root             )                    {
  if (!root) return [];
  const queue                  = [root], result                    = [];
  for (let i = 0; i < queue.length; i++) { const node = queue[i]; if (!node) result.push(null); else { result.push(node.value); queue.push(node.left, node.right); } }
