type Tree = { value: number; left: Tree | null; right: Tree | null };
function readTree(values: (number | null)[]): Tree | null {
  if (values.length === 0 || values[0] === null) return null;
  const root: Tree = { value: values[0], left: null, right: null };
  const queue: Tree[] = [root]; let index = 1;
  for (let i = 0; i < queue.length && index < values.length; i++) {
    const node = queue[i];
    for (const side of ['left', 'right'] as const) {
      const value = values[index++];
      if (value !== null && value !== undefined) { const child: Tree = { value, left: null, right: null }; node[side] = child; queue.push(child); }
    }
  }
  return root;
}
function writeTree(root: Tree | null): (number | null)[] {
  if (!root) return [];
  const queue: (Tree | null)[] = [root], result: (number | null)[] = [];
  for (let i = 0; i < queue.length; i++) { const node = queue[i]; if (!node) result.push(null); else { result.push(node.value); queue.push(node.left, node.right); } }
  while (result[result.length - 1] === null) result.pop();
  return result;
}
export function sortedArrayToBST(values: number[]): (number | null)[] {
  function build(low: number, high: number): Tree | null { if (low > high) return null; const mid = Math.floor((low+high)/2); return {value:values[mid], left:build(low,mid-1), right:build(mid+1,high)}; } return writeTree(build(0,values.length-1));
}
